INSERT INTO "Lesson" (id, current, base) VALUES
  ('base-scout-plan', 1, true),
  ('base-scout-picture', 1, true),
  ('base-scout-ids', 1, true),
  ('base-scout-confirm', 1, true),
  ('base-scout-start-page', 1, true),
  ('base-scout-goal-start', 1, true),
  ('base-supervisor-picture-first', 1, true),
  ('base-supervisor-same-box', 1, true),
  ('base-supervisor-accept', 1, true),
  ('base-supervisor-cheapest-check', 1, true),
  ('base-supervisor-goal-start', 1, true),
  ('base-lessons-start-page', 1, true),
  ('base-lessons-behavior', 1, true)
INSERT INTO "LessonVersion" ("lessonId", version, text, why, signals, area, scope, state, "retiredAtBanks", confidence, seen, evidence, role, audience) VALUES
  ('base-scout-plan', 1, 'Before your first action toward a goal, write a short plan: the screens you expect to cross, from the route so far and what memory knows, and the fewest actions that reach the goal. Each action costs about fifteen seconds, because it is judged before the next.', 'Runs that re-walked screens they already knew ran out of time before the goal.', ARRAY['plan','route','actions','time']::text[], 'pacing', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "4ec1909585224cc609dac8e958104d8fa767a1545d8dd1ebd86ea6cfc75c655e", "seen": true}]'::jsonb, 'curator', 'scout'),
  ('base-scout-picture', 1, 'The picture is the page. The words are a transcription of it: they can hold what a person does not see, such as every option of a closed list, and miss what is drawn as a picture. When they disagree, believe the picture, and match the words to it by their boxes: the same box is the same control, whatever each calls it.', 'A list''s words still named its first option after a choice was made, and the choice was taken for unset while the picture showed it set.', ARRAY['picture','words','list','option','box']::text[], 'rendering', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": ["bank-1/transfer/13"], "hash": "978c51f45c4666c5f7fb249fe9b6e177a8bb252a4ee8cc21a1370aca382af2b3", "seen": true}]'::jsonb, 'curator', 'scout'),
  ('base-scout-ids', 1, 'Prefer a control''s id to a box you estimate: the browser knows where its controls are. After acting by position, check in the picture that it landed where you meant.', 'An estimated box a line too low put a value into the field below the one intended, and the tool still reported the field filled.', ARRAY['id','box','position','field']::text[], 'targeting', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "591b0b512b2f8bcd2f142bd6d6758bb14d1a87ce64ac67757621c28cf9cc5645", "seen": true}]'::jsonb, 'curator', 'scout'),
  ('base-scout-confirm', 1, 'Confirm a step by what the next screen shows, not by redoing it. A form often doesn''t repeat what you entered, and the page after it does. Fix a step on the screen where it went wrong.', 'A review page restates the form''s accounts, amount and memo before anything is sent.', ARRAY['confirm','review','form','redo']::text[], 'pacing', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": ["bank-1/transfer/17"], "hash": "34f75dde2f1e6a11a9c4711880daeafbbd1e44a006fe0d147975b326f8f345a0", "seen": true}]'::jsonb, 'curator', 'scout'),
  ('base-scout-start-page', 1, 'Opening the start page repeats every screen before it: do it only when the browser has truly lost its place, and say why.', 'Two returns to the start page in one goal cost minutes, and the goal.', ARRAY['start','page','restart','lost']::text[], 'navigation', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "0df328ee46e1110cad01db421b2bc1d9d825259db0329f72538572c9cc414221", "seen": true}]'::jsonb, 'curator', 'scout'),
  ('base-scout-goal-start', 1, 'Each goal starts at the bank''s start page on purpose, because that''s where the service starts every task. A browser already signed in may be shown a shorter sign-in there; that is expected, not an error or an expired session.', 'Runs recorded this as an expired session when the factory itself had opened the start page.', ARRAY['start','sign-in','session','goal']::text[], 'session', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": ["bank-1/trusted/09"], "hash": "4288f9f0bebb19ba21150f7e2ffb0e3192b414342e4c45df750e741ded88123a", "seen": true}]'::jsonb, 'curator', 'scout'),
  ('base-supervisor-picture-first', 1, 'Look at the picture first. Never judge that a choice, a typed value or a control is missing from the words or a tool''s answer alone: check the picture and the close-up, and say what the picture shows.', 'A judgment called a choice unset from the words while the picture showed it set, and accepted a tool''s report of a filled field while the picture showed it empty.', ARRAY['picture','close-up','missing','words']::text[], 'evidence', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "e76ea82ada568d13ad3262058ca634a43b932a31c75064dda730e741a61309bb", "seen": true}]'::jsonb, 'curator', 'supervisor'),
  ('base-supervisor-same-box', 1, 'The same box is the same control, whatever the words, the controls and the picture each call it. Compare boxes before calling two names two controls.', 'A send button''s name in the control list differed from the word drawn on it; they shared one box, and taking them for two controls cost the goal.', ARRAY['box','control','name','two']::text[], 'targeting', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "0f32a8e966ab0ed7f209d7d21a911baefa9e6480b4615fd5b61d014589d2874b", "seen": true}]'::jsonb, 'curator', 'supervisor'),
  ('base-supervisor-accept', 1, 'When the Scout says something worked and the picture agrees, accept it. Overrule it only with evidence from the picture.', 'A correct report that a choice was made was overruled from the words alone, and the form was redone twice.', ARRAY['accept','overrule','picture','report']::text[], 'evidence', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "bd5c58ae4ef0868554ea5488f605855596e5d11eb6002bd2b7988682fcb6cc80", "seen": true}]'::jsonb, 'curator', 'supervisor'),
  ('base-supervisor-cheapest-check', 1, 'Prefer the cheapest check: the next screen often confirms a step. Before you advise opening the start page, say why nothing on this screen can fix it.', 'Advice to start over cost every screen before the form, twice.', ARRAY['check','next','screen','start']::text[], 'pacing', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "0876a6f5104ab47f3fb749f6e172c93426ff9e26c1dcc3056e28ef8180592830", "seen": true}]'::jsonb, 'curator', 'supervisor'),
  ('base-supervisor-goal-start', 1, 'Each goal starts at the start page by design; a shorter sign-in there is expected.', 'It was judged a lost session when the factory had opened the start page itself.', ARRAY['start','sign-in','goal','design']::text[], 'session', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": ["bank-1/trusted/09"], "hash": "ae6fae9a67bcef37dd9bb89489dcf342b013ceef9a341a7fb6bf254ce21a6052", "seen": true}]'::jsonb, 'curator', 'supervisor'),
  ('base-lessons-start-page', 1, 'The factory opens the start page before each goal. Never record that as the site''s behavior, such as an interruption or an expired session.', 'Two runs wrote lessons that the session expires, from the factory''s own return to the start page.', ARRAY['lesson','start','session','factory']::text[], 'memory', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "b894863fd4e3d3b3b3fb2c9a589aefecc849150bde9a6293e6b02444c583af2f", "seen": true}]'::jsonb, 'curator', 'both'),
  ('base-lessons-behavior', 1, 'Prefer lessons about how such a site behaves and how to tell (what the picture shows, what the next screen confirms) over lists of its words.', 'The lessons later runs relied on most describe behavior and how to see it, not the site''s words.', ARRAY['lesson','behavior','picture','words']::text[], 'memory', 'pattern', 'confirmed', '{}', 'high', true, '[{"run": "base", "frames": [], "hash": "fb98600b2331bf0c5cffd6afb541d022089414ed40f561a34d4097bdacdead5a", "seen": true}]'::jsonb, 'curator', 'both')
