-- The base lessons: the thirteen lines the postmortem of runs 27 and 28 adopted, for the Scout, the
-- Supervisor and the lesson writer, true of working any such console from the first start, with no
-- run. Confirmed patterns, so every bank's pack serves them to the agent each is for; a run can
-- dispute one, never retire it.

ALTER TABLE "Lesson" ADD COLUMN "base" BOOLEAN NOT NULL DEFAULT false;

-- Whom a lesson is for: the Scout, the Supervisor, or both. Each agent is served its own.
CREATE TYPE "Audience" AS ENUM ('scout', 'supervisor', 'both');
ALTER TABLE "LessonVersion" ADD COLUMN "audience" "Audience" NOT NULL DEFAULT 'both';

ON CONFLICT (id) DO NOTHING;

ON CONFLICT ("lessonId", version) DO NOTHING;
